///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name tbx_search_onkeydown
 * @description tbx_search 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.tbx_search_onkeydown = async function() {
    try {
        if (event.keyCode === 13) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92009.tbx_search_onkeydown" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 조회 버튼
 * @returns {void}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92009.btn_search_onclick" });
    }
};

