///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    // var url = "/listingCommon.do?method=listCorpChrg&inputMessageId=CORP_CHRG_OUT&outputMessageId=CORP_CHRG_OUT" + "&COM_ABBRV=" + tbx_search.value +"&SECUGRP_ID=" + fr_SecuGrpId;
    // var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listCorpChrg&inputMessageId=CORP_CHRG_OUT&outputMessageId=CORP_CHRG_OUT"
    //  + "&SECUGRP_ID=" + scwin.fr_SecuGrpId + "&COM_ABBRV=" + tbx_search.getValue() + "&MARKET=" + scwin.fr_MktId;
    // //dts.DataID = fn_encodeNSession(url);
    // dts.DataID = encodeURI(url);
    // dts.reset();

    dma_selectListCorpChrgReq.set("secugrpId", scwin.fr_SecuGrpId); // 증권그룹ID
    dma_selectListCorpChrgReq.set("mktTpCd", scwin.fr_MktId); // 시장구분값
    dma_selectListCorpChrgReq.set("comAbbrv", tbx_search.getValue()); // 회사약명
    const sbmOptions = {
        id: "sbm_selectListCorpChrg",
        action: "/api/listing/common/pop/issur/select-list-corp-chrg",
        method: "get",
        ref: "dma_selectListCorpChrgReq",
        target: "dlt_selectListCorpChrgRes=body",
        isProcessMsg : true
    };
    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_selectListCorpChrg_submitdone(sbmRtn);
};

/**
 * @method
 * @name sbm_selectListCorpChrg_submitdone
 * @description selectListCorpChrg 통신 후처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_selectListCorpChrg_submitdone = async function(e) {
    const res = e.responseJSON;
    if (res.success === false) {
        await $c.win.alert(res.errors);
    } else {
        tbx_totCnt.setValue(dlt_selectListCorpChrgRes.getRowCount());

        // 초기1회 초기값으로 설정된 회사코드를 검색한다.
        // if (scwin.strCdSch != "") {
        //     for (let i = 0; i < dts.getRowCount(); i++) {
        //         if (scwin.strCdSch == dts.getCellData(i, 1)) {
        //             dts.setRowPosition(i, 0);
        //             break;
        //         }
        //     }
        //     scwin.strCdSch = "";
        // }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name mktTpCd
 * @description 시장구분 코드 → 시장명(유가/코스닥/코넥스) 변환
 * @param {*} data 데이터
 * @returns {*}
 * @hidden N
 */
scwin.mktTpCd = function(data){
    let rtnValue = "";
    switch (data) {
    case "1":
        rtnValue = "유가";
        break;
    case "2":
        rtnValue = "코스닥";
        break;
    case "6":
        rtnValue = "코넥스";
        break;
    default:
        rtnValue = "기타";
        break;
    }
    return rtnValue;
};
